{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PRESENT",
      "chunk_id": "text_6",
      "quote": "Population: women undergoing outpatient or office-based blind endometrial biopsy or endometrial sampling for any clinical indication. Intervention: peri-procedural analgesic, anesthetic, or pain-control strategies... Comparator: placebo, normal saline, placebo gel, distilled water, or another credible inert control... Outcomes: the primary outcome was pain during biopsy or sampling on a 0-10 compatible scale... Study design: randomized controlled trials were eligible for efficacy synthesis",
      "reason": "Full PICO framework with population, intervention, comparator, outcomes, and eligible study designs is explicitly specified."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PRESENT",
      "chunk_id": "text_7",
      "quote": "No restrictions were placed on publication year, language, country, indication for biopsy, menopausal status, or biopsy device",
      "reason": "Report characteristics (year, language, publication status) are addressed by explicitly stating no restrictions; handling of abstracts, registry entries, and secondary reports is also specified."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "PARTIAL",
      "chunk_id": "text_7",
      "quote": "reports without usable pain or safety outcomes were excluded from review synthesis",
      "reason": "Exclusion categories distinguish records lacking extractable results (e.g., 'no public extractable results', median-only reporting) from those without the outcome measured, but the review does not explicitly separate 'outcome not measured' from 'outcome measured but not reported'."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PRESENT",
      "chunk_id": "text_7",
      "quote": "To avoid mixing clinically different comparisons, we organized the evidence into three tiers. Tier 1 was the prespecified primary meta-analysis. It included inert-controlled randomized comparisons with extractable intra-procedural means and standard deviations. Tier 2 comprised sensitivity analyses... Tier 3 comprised narrative or tabulated contextual evidence.",
      "reason": "Synthesis groups (three tiers) are explicitly specified and linked to the comparison types (inert-controlled vs active-comparator, co-intervention, etc.) defined in the objectives."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "PRESENT",
      "chunk_id": "text_7",
      "quote": "Studies were excluded from the primary analysis when they centered on hysteroscopy-guided biopsy... because those settings differ in instrumentation, duration, uterine distension, cervical manipulation, and pain mechanisms.",
      "reason": "Rationales for notable eligibility restrictions (procedure type, inert comparator requirement, extractable data) are explicitly provided."
    }
  ],
  "confidence": 90
}

